-- Q00 · A instalação ficou no staging, com exatamente as tabelas previstas.
-- Mesmo limite do P00: a identidade do alvo confirma-se fora do SQL.
-- Só leitura: um único SELECT. Resultado: uma linha por verificação. Se alguma
-- verificação falhar (ou der NULL), a consulta TERMINA EM ERRO com "REPROVADO: <id> obtido=<valor> | …".
WITH pt AS (SELECT c.oid, c.relname::text AS nome FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p', 'v', 'm', 'f')),
c(id, verificacao, ok, esperado, obtido) AS (
  SELECT 'Q00-01'::text, 'existe public.staging_notes (marca do staging)'::text, (to_regclass('public.staging_notes') IS NOT NULL)::boolean, 'sim'::text, (CASE WHEN to_regclass('public.staging_notes') IS NULL THEN 'não' ELSE 'sim' END)::text
  UNION ALL SELECT 'Q00-02'::text, 'tabelas em public = 106 previstas (104 V2 + 2 do staging)'::text, ((SELECT count(*) FROM pt) = 106 AND encode(sha256(convert_to((SELECT string_agg(nome, ',' ORDER BY nome COLLATE "C") FROM pt), 'UTF8')), 'hex') = '01be7eeb32fb5822b12cbc5698cc349f799d0a51aeee0ba311049c3b5e287742')::boolean, '106 / 01be7eeb32fb5822b12cbc5698cc349f799d0a51aeee0ba311049c3b5e287742'::text, ((SELECT count(*) FROM pt)::text || ' / em falta: ' || coalesce((SELECT string_agg(x, ',') FROM (SELECT unnest(ARRAY['access_invite_attempts', 'access_invites', 'access_waitlist', 'account_access', 'admin_audit_logs', 'admin_broadcast_recipients', 'admin_broadcasts', 'admin_cost_settings', 'admin_messages', 'admin_mfa_required', 'ai_model_rates', 'alert_mutes', 'announcement_dismissals', 'app_settings', 'app_user_connection_aliases', 'app_user_connections', 'assessor_ai_logs', 'assessor_messages', 'assessor_nudges', 'assessor_quality_scores', 'assessor_reasoning_traces', 'assessor_tool_calls', 'assistant_golden_conversations', 'assistant_golden_runs', 'assistant_reflections', 'assistant_shadow_runs', 'assistant_trust_scores', 'assistant_user_corrections', 'autonomy_rules', 'billing_test_accounts', 'calendar_connections', 'calendar_event_links', 'calendar_sync_log', 'calendar_sync_state', 'channel_links', 'consultant_preferences', 'content_access_consents', 'conversation_locks', 'conversation_states', 'daily_digests', 'daily_priorities', 'dashboard_announcements', 'dashboard_login_tokens', 'deal_deadlines', 'email_connections', 'email_drafts', 'email_messages', 'email_threads', 'entity_tags', 'event_categories', 'feature_flag_users', 'feature_flags', 'file_categories', 'file_links', 'financial_movements', 'folder_items', 'folders', 'follow_ups', 'inbound_message_claims', 'interactions', 'invite_send_attempts', 'landing_page_visits', 'mentor_decisions', 'miscellaneous_items', 'opportunities', 'opportunity_events', 'opportunity_properties', 'pending_actions', 'people', 'person_phones', 'pilot_invite_deliveries', 'pilot_participants', 'pilots', 'plan_configs', 'proactive_daily_ledger', 'product_feedback', 'product_telemetry_events', 'product_updates', 'profiles', 'promo_codes', 'promo_redemptions', 'properties', 'property_categories', 'property_interests', 'property_marketing_activities', 'property_offers', 'prospecting_leads', 'reminders', 'routines', 'short_links', 'similar_listing_searches', 'staging_notes', 'stripe_webhook_events', 'subscription_events', 'support_sessions', 'tags', 'telegram_invites', 'telegram_link_tokens', 'telegram_pairings', 'uploaded_files', 'user_roles', 'whatsapp_link_codes', 'whatsapp_proactive_tests', 'whatsapp_send_logs', 'whatsapp_template_bindings', 'whatsapp_template_rates']::text[]) AS x EXCEPT SELECT k FROM (SELECT nome FROM pt) a(k)) d), '-') || ' / a mais: ' || coalesce((SELECT string_agg(x, ',') FROM (SELECT k AS x FROM (SELECT nome FROM pt) a(k) EXCEPT SELECT unnest(ARRAY['access_invite_attempts', 'access_invites', 'access_waitlist', 'account_access', 'admin_audit_logs', 'admin_broadcast_recipients', 'admin_broadcasts', 'admin_cost_settings', 'admin_messages', 'admin_mfa_required', 'ai_model_rates', 'alert_mutes', 'announcement_dismissals', 'app_settings', 'app_user_connection_aliases', 'app_user_connections', 'assessor_ai_logs', 'assessor_messages', 'assessor_nudges', 'assessor_quality_scores', 'assessor_reasoning_traces', 'assessor_tool_calls', 'assistant_golden_conversations', 'assistant_golden_runs', 'assistant_reflections', 'assistant_shadow_runs', 'assistant_trust_scores', 'assistant_user_corrections', 'autonomy_rules', 'billing_test_accounts', 'calendar_connections', 'calendar_event_links', 'calendar_sync_log', 'calendar_sync_state', 'channel_links', 'consultant_preferences', 'content_access_consents', 'conversation_locks', 'conversation_states', 'daily_digests', 'daily_priorities', 'dashboard_announcements', 'dashboard_login_tokens', 'deal_deadlines', 'email_connections', 'email_drafts', 'email_messages', 'email_threads', 'entity_tags', 'event_categories', 'feature_flag_users', 'feature_flags', 'file_categories', 'file_links', 'financial_movements', 'folder_items', 'folders', 'follow_ups', 'inbound_message_claims', 'interactions', 'invite_send_attempts', 'landing_page_visits', 'mentor_decisions', 'miscellaneous_items', 'opportunities', 'opportunity_events', 'opportunity_properties', 'pending_actions', 'people', 'person_phones', 'pilot_invite_deliveries', 'pilot_participants', 'pilots', 'plan_configs', 'proactive_daily_ledger', 'product_feedback', 'product_telemetry_events', 'product_updates', 'profiles', 'promo_codes', 'promo_redemptions', 'properties', 'property_categories', 'property_interests', 'property_marketing_activities', 'property_offers', 'prospecting_leads', 'reminders', 'routines', 'short_links', 'similar_listing_searches', 'staging_notes', 'stripe_webhook_events', 'subscription_events', 'support_sessions', 'tags', 'telegram_invites', 'telegram_link_tokens', 'telegram_pairings', 'uploaded_files', 'user_roles', 'whatsapp_link_codes', 'whatsapp_proactive_tests', 'whatsapp_send_logs', 'whatsapp_template_bindings', 'whatsapp_template_rates']::text[])) d), '-'))::text
  UNION ALL SELECT 'Q00-03'::text, 'nenhuma vista, vista materializada ou tabela externa em public'::text, (NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind IN ('v', 'm', 'f')))::boolean, 'nenhuma'::text, ((SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind IN ('v', 'm', 'f'))::text)::text
),
v AS (SELECT count(*) AS n, string_agg(id || ' obtido=' || left(coalesce(obtido, 'NULL'), 160), ' | ' ORDER BY id) FILTER (WHERE ok IS NOT TRUE) AS falhas FROM c)
SELECT c.id, c.verificacao, CASE WHEN c.ok IS TRUE THEN 'OK' ELSE 'FALHA' END AS estado, c.esperado, c.obtido,
       CASE WHEN v.n <> 3 THEN ('VEREDITO INVÁLIDO: ' || v.n::text || ' verificações')::int::text
            WHEN v.falhas IS NULL THEN 'APROVADO'
            ELSE ('REPROVADO: ' || v.falhas)::int::text END AS veredito
  FROM c CROSS JOIN v ORDER BY c.id;
